L39_1.m_Talk_TWN = "<color=#ffd34c>觀測組，立刻回報！現在畫面拍到的到底是什麼東西！</color>"
L39_1.m_Talk_SCN = "<color=#ffd34c>观察组，快报告！现在视频中拍到的东西究竟是什么！</color>"
