L28_1 = "Tch! Old-fashioned like an ex-soldier always is. You think I don't know that?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "嘖，又是那套退役軍人的老掉牙說辭。當我不知道？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "切，又是那套退役军人的老掉牙说辞。当我不知道？"
