L32_1 = "CHARADE_ADMIN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "대정화 전쟁의 영웅, 마리아 안토노프 중장이 관리국에 보낸 좌표 송신기다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "大浄化戦争の英雄、マリア・アントノフ中将から管理局に送られてきた座標送信機だ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "It's a coordinates transmitter sent to the Administration from the hero of the Grand Purification War, Lieutenant General Antonov."
L31_1.m_Talk_ENG = L32_1
L32_1 = "這個是大淨化戰爭中的英雄，瑪利亞·安東諾夫中將提供給管理局的座標發射器。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "这个是净化作战中的英雄，玛丽亚·安东中将提供给管理局的坐标发射器。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "It's a coordinates transmitter sent to the Administration from the hero of the Grand Purification War, Lieutenant General Antonov."
L31_1.m_Talk_DEU = L32_1
