L33_1 = "SWANSONG_ACT1_PROLOGUE@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 6800101
L32_1.m_CutScenStrID = "SWANSONG_ACT1_PROLOGUE"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "CHARADE_ADMIN_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "중장은 적진에 도착하면, 이걸로 신호를 보내 해당 이면세계의 좌표를 송신하겠다더군."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "中将は敵陣に着く次第、これを媒介にその裏世界の座標を送信すると言った。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Lieutenant General said she'll send us the Counterside coordinates once she arrives at the enemy camp."
L32_1.m_Talk_ENG = L33_1
L33_1 = "中將表示她在到達敵陣後，會用這個發送信號，傳送該異界的座標位置。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "中将表示她在到达敌阵后，会用这个发送信号，传送该异界的坐标位置。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Lieutenant General said she'll send us the Counterside coordinates once she arrives at the enemy camp."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Lieutenant General said she'll send us the Counterside coordinates once she arrives at the enemy camp."
L32_1.m_Talk_FRA = L33_1
