L34_1 = "SWANSONG_ACT1_PROLOGUE@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 6800101
L33_1.m_CutScenStrID = "SWANSONG_ACT1_PROLOGUE"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "CHARADE_ADMIN_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "델타 세븐이 보유한 시공가속기로 두 공간을 직접 연결하는 대규모 증원 작전, <color=#ffd34c>프리덤 스트라이크</color>를 수행할 수 있도록 말이야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "デルタセブンが保有している時空加速器で二つの空間を直接繋げる大規模増援作戦、<color=#ffd34c>フリーダムストライク</color>を遂行できるようにな。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "So that we can carry out <color=#ffd34c>Freedom Strike</color>, the large-scale operation that directly connects the two spaces using the time-space accelerator owned by Delta Seven."
L33_1.m_Talk_ENG = L34_1
L34_1 = "之後就可以利用第七三角洲部隊持有的時空加速器，直接連接兩個空間，執行名為<color=#ffd34c>自由之擊</color>大規模增援作戰。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "之后就可以利用德尔塔部队持有的时空加速器，直接连接两个空间，执行名为<color=#ffd34c>自由之击</color>大规模增援作战。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "So that we can carry out <color=#ffd34c>Freedom Strike</color>, the large-scale operation that directly connects the two spaces using the time-space accelerator owned by Delta Seven."
L33_1.m_Talk_DEU = L34_1
L34_1 = "So that we can carry out <color=#ffd34c>Freedom Strike</color>, the large-scale operation that directly connects the two spaces using the time-space accelerator owned by Delta Seven."
L33_1.m_Talk_FRA = L34_1
