L39_1 = "GROUND_ADMIN_NULL_NULL"
L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "지금 인위적으로 생성한 차원 균열에 저렇게 많은 태스크포스 병력을 밀어 넣겠다는 거야?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "人工的に生成した次元の亀裂に、あんな大勢のタスクフォース兵力を送り込む？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "So, we're going to shove that many TASKFORCEs into an artificially created dimensional rift?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "是要把那麼多特遣兵力強行塞進人工生成的次元裂縫裡嗎？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "是要把那么多特遣兵力强行塞进人工生成的次元裂缝里吗？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "So, we're going to shove that many TASKFORCEs into an artificially created dimensional rift?"
L38_1.m_Talk_DEU = L39_1
