L6_1 = "JACKSON_CHAMBER_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "클리포트 게임에서 패배한다면, 또다시 관리실패와 같은 사태가 발생하겠지."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "クリフォトゲームで敗北すると、再び管理失敗のような事態が発生するだろう。"
