L7_1 = "JACKSON_CHAMBER_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "하지만 여섯 도시를 대표하는 우리의 최우선 목표는 어디까지나 질서의 수호."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "しかし六つの都市を代表する私たちの最優先目標は、あくまで秩序の守護。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "The six city representatives' top priority is to protect the order."
