L8_1 = "JACKSON_CHAMBER_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "따라서 저들에게 클리포트 게임의 실체와 있는 그대로의 진실을 공표할 수는 없다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "よって、彼らにクリフォトゲームの実態や詳しい真相を公表することはできない。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "So, we cannot reveal the blatant truth of the Qliphoth Game to them as it is."
L7_1.m_Talk_ENG = L8_1
L8_1 = "因此還不能向世界公佈逆卡巴拉遊戲的真相和實際情況。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "因此还不能向世界公布神圣战役的真相和实际情况。"
