L8_1.m_CharStrID = L9_1
L9_1 = "결론, 모든 일이 무사히 끝나더라도 누군가는 반드시 이 사태에 대한 책임을 져야 한다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "結論。すべてが無事に終わっても、誰かは必ずこの事態に対して責任を取らねばならない。"
