L34_1 = "그나저나 까다로운 리하르트의 눈을 피해, 샤레이드 비서관 중 하나로 잠입하다니……."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それはそうとして、あの厳しいリヒャルトの目を掻いくぐりシャレードの秘書官として潜入するとは……"
L33_1.m_Talk_JPN = L34_1
L34_1 = "By the way, sneaking in as one of Charade's secretaries while avoiding Richard's keen eye..."
L33_1.m_Talk_ENG = L34_1
L34_1 = "話說回來，能避開挑剔的理查的眼睛，潛入成為查雷德的秘書之一……"
L33_1.m_Talk_TWN = L34_1
L34_1 = "话说回来，能避开挑剔的理查德的眼睛，潜入成为查雷德的秘书之一……"
L33_1.m_Talk_SCN = L34_1
L34_1 = "By the way, sneaking in as one of Charade's secretaries while avoiding Richard's keen eye..."
L33_1.m_Talk_DEU = L34_1
