L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "아무리 겉모습을 빌릴지라도, 배역에 대한 이해가 부족하면 티가 나기 마련이랍니다."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "見た目をどれだけ巧妙に装っても、配役への理解が不足していればすぐにバレるものです。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "No matter what appearance I borrow, a lack of understanding of the role is bound to be noticeable."
L38_1.m_Talk_ENG = L39_1
L39_1 = "無論外表如何相似，如果對角色的理解不足，總會露出破綻。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "无论外表如何相似，如果对角色的理解不足，总会露出破绽。"
