L49_1.m_CharStrID = L50_1
L50_1 = "이를 통해, 늑대가 리플레이서 사태에 깊게 관련되도록 만들었습니다."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それによって、オオカミがリプレイサー事件に深く関わるように画策しました。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Through that, you made the Wolf get deeply involved in the Replacer incident."
L49_1.m_Talk_ENG = L50_1
L50_1 = "透過這一處理，讓狼捲入了克隆事件。"
