L8_1 = "SWAN_SIX_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "또한 당신은 저를 통해, 원래라면 구원기사단이 절대 알 수 없는 정보."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そして、あなたは私を通して本来なら救世騎士団が知りえるはずのない情報……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Also, through me, you leaked information that the Knights of Redemption would have never known."
L7_1.m_Talk_ENG = L8_1
L8_1 = "此外，透過我，你們得到了原本救贖騎士團絕對無法知道的資訊。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "此外，通过我，你们得到了原本救援骑士团绝对无法知道的信息。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Also, through me, you leaked information that the Knights of Redemption would have never known."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Also, through me, you leaked information that the Knights of Redemption would have never known."
L7_1.m_Talk_FRA = L8_1
