L8_1.m_CharStrID = L9_1
L9_1 = "<color=#ffd34c>등대</color>에 관한 정보를 흘렸고, 그들이 그것을 손에 넣게 만들었죠."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "<color=#ffd34c>灯台</color>に関する情報を流し、彼らがそれを入手するように仕向けた。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Which allowed them to get their hands on it. The <color=#ffd34c>Lighthouse</color>."
L8_1.m_Talk_ENG = L9_1
L9_1 = "之後你又把<color=#ffd34c>燈塔</color>的相關情報透露給了他們，好讓他們得手。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "之后你又把<color=#ffd34c>灯塔</color>的相关情报透露给了他们，好让他们得手。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Which allowed them to get their hands on it. The <color=#ffd34c>Lighthouse</color>."
