L12_1 = "SWAN_SIX_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "덕분에 그들은 클리포트 게임의 조건 중 하나였던 허신을 손쉽게 불러낼 수 있었습니다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "おかげで彼らはクリフォトゲームの条件の一つだった、虚神を容易く呼び出すことができました。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "As a result of that, they were able to easily summon the Hollow God, which was one of the requirements of the Qliphoth Game."
L11_1.m_Talk_ENG = L12_1
L12_1 = "多虧於此，才輕鬆地召喚出了逆卡巴拉遊戲開啟條件之一的幻神。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "多亏于此，才轻松地召唤出了神圣战役开启条件之一的虚神。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "As a result of that, they were able to easily summon the Hollow God, which was one of the requirements of the Qliphoth Game."
L11_1.m_Talk_DEU = L12_1
L12_1 = "As a result of that, they were able to easily summon the Hollow God, which was one of the requirements of the Qliphoth Game."
