L17_1 = "SWAN_SIX_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "한편으로 그렇게 소환된 허신을 늑대가 수월하게 쓰러트릴 수 있도록."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "一方で、オオカミがその召喚された虚神を倒しやすいように……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "On the other hand, you made it easier for the Wolf to defeat the summoned Hollow God."
L16_1.m_Talk_ENG = L17_1
L17_1 = "另一方面，你為了讓被召喚出的幻神能被狼輕鬆擊敗。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "另一方面，你为了让被召唤出的虚神能被狼轻松击败。"
