L18_1 = "SWAN_SIX_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "협력자들에게 미리 구 관리국의 유산, 테크 레벨 5의 설계도를 유출시켜 두었고요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "予め、旧管理局の遺産であるテックレベル5の設計図を、彼女の協力者たちに流しておいた。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "By leaking the Old Administration's legacy, the blueprint of Tech Level 5, to your collaborators in advance."
L17_1.m_Talk_ENG = L18_1
L18_1 = "提前向合作夥伴洩露了舊管理局的遺產，技術等級5的設計圖。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "提前向合作伙伴泄露了旧管理局的遗产，技术等级5的设计图。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "By leaking the Old Administration's legacy, the blueprint of Tech Level 5, to your collaborators in advance."
