L47_1 = "그들은 관리자님께 반감을 가지고 있지만, 결국 프리덤 스트라이크에 응하겠죠."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "彼らは管理者に反感を持ちながらも、最終的にはフリーダムストライクに応じるでしょう。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Though they have animosity toward the Administrator, they will eventually agree to Freedom Strike."
L46_1.m_Talk_ENG = L47_1
L47_1 = "他們雖然對管理者不滿，但最終還是會回應自由之擊作戰。"
L46_1.m_Talk_TWN = L47_1
