L48_1 = "왜냐하면 그들에게는 지켜야만 하는 것들이 존재하기 때문이에요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "彼らには守らなければならないものが存在するからです。"
