L49_1 = "인간은 잃지 않기 위해서라면, 혹은 잃은 것을 되돌리기 위해서라면……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "失わないために、あるいは失ってしまったものを取り戻すためなら……"
