L8_1 = "뭐, 스승님과는 다르게 저는 이 세계의 잠재력. 그리고 관리자님을 믿고 있거든요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "まあ、師匠とは違って僕はこの世界の潜在力と、管理者を信じているので。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Well, I am this world's potential, unlike Master. And I trust the Administrator."
L7_1.m_Talk_ENG = L8_1
L8_1 = "嗯，我和師父不同，我相信這個世界的潛力。還有管理者。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "嗯，我和老师不同，我相信这个世界的潜力。还有管理者大人。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Well, I am this world's potential, unlike Master. And I trust the Administrator."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Well, I am this world's potential, unlike Master. And I trust the Administrator."
L7_1.m_Talk_FRA = L8_1
