L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "역사적으로도 인류는 공공의 적을 설정하여 난관을 극복한 사례가 적지는 않습니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "歴史的にも、人類は共通の敵を設けて難関を乗り越えてきました。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Throughout history, there have been many examples of humanity overcoming hardship by targeting a common enemy."
L10_1.m_Talk_ENG = L11_1
L11_1 = "即使從歷史上看，人類通過設定共同的敵人來克服困難的例子並不少見。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "即使从历史上看，人类通过设定共同的敌人来克服困难的例子并不少见。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Throughout history, there have been many examples of humanity overcoming hardship by targeting a common enemy."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Throughout history, there have been many examples of humanity overcoming hardship by targeting a common enemy."
L10_1.m_Talk_FRA = L11_1
