L44_1 = "NAYUBIN_SIX_NULL_NULL"
L43_1.m_CharStrID = L44_1
L44_1 = "그나저나 이렇게 안아 드니까 옛날 생각 나네."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "それにしても、こういうふうに抱きかかえていると、昔を思い出すな。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Holding you like this reminds me of the old days."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不過這樣抱著你，倒是讓我想起了以前的事。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "不过这样抱着你，倒是让我想起了以前的事。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Holding you like this reminds me of the old days."
L43_1.m_Talk_DEU = L44_1
