L45_1 = "SWANSONG_ACT1_PROLOGUE@244#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 244
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 6800101
L44_1.m_CutScenStrID = "SWANSONG_ACT1_PROLOGUE"
