L45_1 = "NAYUBIN_SIX_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "네가 날뛰다가 부상 입은 날이면 의료실까지 데려가는 건 늘 내 몫이었지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "君が暴れて怪我をすれば、治療室まで運ぶのはいつだって僕の役目だった。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I was always in charge of taking you to the infirmary, whenever you went on a rampage and hurt yourself."
L44_1.m_Talk_ENG = L45_1
L45_1 = "每次你因為胡鬧而受傷，都是我負責送去醫務室的。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "每次你因为胡闹而受伤，都是我负责送去医务室的。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "I was always in charge of taking you to the infirmary, whenever you went on a rampage and hurt yourself."
L44_1.m_Talk_DEU = L45_1
L45_1 = "I was always in charge of taking you to the infirmary, whenever you went on a rampage and hurt yourself."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "SWANSONG_ACT1_PROLOGUE@245#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 245
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 6800101
