L46_1 = "NAYUBIN_SIX_NULL_NULL"
L45_1.m_CharStrID = L46_1
L46_1 = "다른 전대원들 눈에 띄면 스승님 이름에 먹칠을 했다면서 펄펄 뛰었고."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "それが他の戦隊員たちにバレると、師匠の顔に泥を塗ったと言ってすごく怒ってたっけ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "You would get furious when the other divisions spotted you, yelling that you were being a disgrace to Master's honor."
L45_1.m_Talk_ENG = L46_1
L46_1 = "被戰隊其他隊員看到的時候，還跳著腳嚷嚷什麼“給師父丟臉了”之類的話。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "被战队其他队员看到的时候，还差点跳起来嚷嚷什么“给老师丢脸了”之类的话。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "You would get furious when the other divisions spotted you, yelling that you were being a disgrace to Master's honor."
L45_1.m_Talk_DEU = L46_1
L46_1 = "You would get furious when the other divisions spotted you, yelling that you were being a disgrace to Master's honor."
L45_1.m_Talk_FRA = L46_1
