L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "하하, 정말 한결같네. 여전히 어릴 때처럼 나서지 않고는 못배기다니."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "はは、本当に君は変わらないね。小さい頃から自分が行かないと我慢できないその性格は。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Ha ha. You never change, do you? You just can't resist the spotlight."
L48_1.m_Talk_ENG = L49_1
L49_1 = "哈哈，你真是一點都沒變。還是像小時候一樣，忍不住會站出來。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "哈哈，你真是一点都没变。还是像小时候一样，忍不住会站出来。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ha ha. You never change, do you? You just can't resist the spotlight."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Ha ha. You never change, do you? You just can't resist the spotlight."
L48_1.m_Talk_FRA = L49_1
