L49_1.m_fTalkTime = 0.03
L50_1 = "……あの日以来、もう現場に戻ってきてほしくなかったんだけど。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "...I really hoped you wouldn't have to come back to the field after that day."
L49_1.m_Talk_ENG = L50_1
L50_1 = "……我真希望，自那天之後，你就再也不用回到前線。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "……我真希望，自那天之后，你就再也不用回到前线。"
